export const CORPUS_V2_SEED = 'quoky-adr-0124-ch1-v2-2026-11-05';

/** A section of a titled document closes once it holds about this many code points (3,000 for the ADR file). */
export const DRIVE_SECTION_CODE_POINTS = 2_000;
export const ADR_SECTION_CODE_POINTS = 3_000;
/** A long paragraph is drawn between 1,300 and this many code points; filler sentences (up to about 150) may overshoot, so it stays under 4,000. */
export const LONG_PARAGRAPH_MAX = 3_850;
/** The 2 MiB ADR tier is reduced to 3 cases (one per language, depths 30 / 50 / 70): the 15-case tier made v1 slow and said nothing new. */
export const ADR_FILE_V2_DEPTH_AT = [1, 2, 3] as const;

export type QuestionMode = 'named' | 'paraphrase' | 'section';
export type FeatureTag =
  | 'named'
  | 'paraphrase'
  | 'section-name'
  | 'no-codename'
  | 'long-paragraph'
  | 'lp-middle'
  | 'lp-cut'
  | 'near-duplicate'
  | 'dense'
  | 'topic-shared'
  | 'topic-disjoint';
export const FEATURE_TAGS: readonly FeatureTag[] = ['named', 'paraphrase', 'section-name', 'no-codename', 'long-paragraph', 'lp-middle', 'lp-cut', 'near-duplicate', 'dense', 'topic-shared', 'topic-disjoint'];

export interface NearDuplicate {
  readonly kind: NeedleKind;
  readonly slots: Slots;
  readonly text: string;
  /** Code-point range of the decoy sentence or row in `prepared`. */
  readonly start: number;
  readonly end: number;
}

export interface ChunkEvalCaseV2 extends ChunkEvalCase {
  readonly codename: string;
  /** The needle's own topic phrase and the phrase the paraphrased question uses for it. */
  readonly topic: { readonly needle: string; readonly question: string };
  /** The answer-bearing values of the needle; none occurs in a paraphrase or section question. */
  readonly answers: readonly string[];
  readonly mode: QuestionMode;
  readonly tags: readonly FeatureTag[];
  /** The paragraph (or sheet row) holding the needle, for long-paragraph cases. Code-point range in `prepared`. */
  readonly longParagraph?: { readonly placement: 'middle' | 'cut'; readonly start: number; readonly end: number; readonly needleFraction: number };
  readonly nearDuplicates: readonly NearDuplicate[];
  /** The named section (section-name cases): its number, title and code-point range (title line through the section's last block). */
  readonly section?: { readonly number: number; readonly title: string; readonly start: number; readonly end: number };
  /** Drive doc, section-name cases only: the text / Markdown pair. */
  readonly pairId?: string;
  readonly format?: 'text' | 'markdown';
}

