const DOMAIN_EN = ['Refund', 'Shipping', 'Warranty', 'Onboarding', 'Security', 'Licensing', 'Billing', 'Privacy', 'Procurement', 'Maintenance', 'Travel', 'Training'];
const DOMAIN_KO = ['환불', '배송', '보증', '온보딩', '보안', '라이선스', '청구', '개인정보', '조달', '유지보수', '출장', '교육'];
const KIND_EN = ['policy', 'schedule', 'process', 'requirements', 'exceptions', 'responsibilities'];
const KIND_KO = ['정책', '일정', '절차', '요건', '예외', '책임'];
