// ---------------------------------------------------------------- values

function slotValues(kind: NeedleKind, language: Language, random: Random, subject: string, topic: string): SlotsV2 {
  switch (kind) {
    case 'date': {
      const a = day(random, language);
      let b = day(random, language);
      while (b === a) b = day(random, language);
      return { subject, topic, a, b };
    }
    case 'amount':
      return { subject, topic, a: money(random), b: '' };
    case 'decision':
      return { subject, topic, a: pick(random, language === 'en' ? OPTIONS_EN : OPTIONS_KO), b: '' };
    case 'role':
      return { subject, topic, a: person(random, language), b: '' };
    case 'sheet-row':
      return { subject, topic, a: `${person(random, language)} | ${money(random)} | ${day(random, language)}`, b: '' };
    case 'code-line':
      // Four digits: a value the question (which may carry a section number below 1,000) can never contain by chance.
      return { subject, topic, a: String(between(random, 1000, 9999)), b: '' };
  }
}

const answersOf = (kind: NeedleKind, s: Slots): string[] => (kind === 'date' ? [s.a, s.b] : kind === 'sheet-row' ? s.a.split(' | ') : [s.a]);

// ---------------------------------------------------------------- the model of one item

interface Sec {
  readonly title: string | null;
  readonly units: string[];
}
interface Part {
  readonly frame: string;
  readonly title: string;
  readonly table: boolean;
  readonly lead: string | null;
  readonly secs: Sec[];
}

const renderBody = (part: Part, separator: string, format: 'text' | 'markdown'): { body: string; titleStarts: number[] } => {
  const blocks: string[] = [];
  const marks = new Set<number>();
  if (part.lead !== null) blocks.push(format === 'markdown' ? `# ${part.lead}` : part.lead);
  for (const sec of part.secs) {
    if (sec.title !== null) {
      marks.add(blocks.length);
      blocks.push(format === 'markdown' ? `## ${sec.title}` : sec.title);
    }
    blocks.push(...sec.units);
  }
  const starts: number[] = [];
  let at = 0;
  blocks.forEach((block, order) => {
    if (marks.has(order)) starts.push(at);
    at += block.length + separator.length;
  });
  return { body: blocks.join(separator), titleStarts: starts };
};

interface Candidate {
  readonly part: number;
  readonly sec: number;
  readonly at: number;
  readonly start: number;
}

/** Every unit boundary with the code-point offset at which a unit inserted there would start in the serialized item. */
function boundaries(parts: readonly Part[], table: boolean): { candidates: Candidate[]; total: number } {
  const gap = table ? 1 : 2;
  const candidates: Candidate[] = [];
  let pos = 0;
  parts.forEach((part, partAt) => {
    let blocks = 0;
    const advance = (length: number): void => {
      pos += length + gap;
      blocks += 1;
    };
    if (part.lead !== null) advance(cpLength(part.lead));
    part.secs.forEach((sec, secAt) => {
      if (sec.title !== null) advance(cpLength(sec.title));
      for (let at = 0; at <= sec.units.length; at += 1) {
        if (!(part.table && at === 0)) candidates.push({ part: partAt, sec: secAt, at, start: pos });
        if (at < sec.units.length) advance(cpLength(sec.units[at] as string));
      }
    });
    if (blocks > 0) pos -= gap;
    pos += 2;
  });
  return { candidates, total: pos - 2 };
}

// ---------------------------------------------------------------- long paragraph

interface LongParagraph {
  readonly text: string;
  /** Code-point offset of the needle text inside `text`. */
  readonly needleOffset: number;
}

/** Filler sentences (v1's) up to `size` code points; the needle (or a sheet row) goes in at a sentence boundary chosen by `target`. */
function longParagraph(random: Random, language: Language, names: readonly string[], codename: string, size: number, needle: string, target: number, table: boolean, middleThird = false): LongParagraph {
  const sentences: string[] = [];
  let points = 0;
  while (points < size - cpLength(needle)) {
    const sentence = fillerSentence(random, language, names, codename);
    sentences.push(sentence);
    points += cpLength(sentence) + 1;
  }
  // lp-middle: only boundaries inside the middle third of the finished paragraph qualify.
  const total = points + cpLength(needle);
  const inWindow = (offset: number): boolean => !middleThird || (offset >= total / 3 + 24 && offset <= (2 * total) / 3 - 24);
  let best = -1;
  let bestError = Infinity;
  let offset = 0;
  sentences.forEach((sentence, at) => {
    const error = Math.abs(offset - target);
    if (inWindow(offset) && error < bestError) {
      best = at;
      bestError = error;
    }
    offset += cpLength(sentence) + 1;
  });
  if (best < 0) best = Math.max(0, Math.floor(sentences.length / 2));
  const pre = sentences.slice(0, best).join(' ');
  const post = sentences.slice(best).join(' ');
  const joiner = table ? ' | ' : ' ';
  const text = [pre, needle, post].filter((piece) => piece !== '').join(joiner);
  return { text, needleOffset: pre === '' ? 0 : cpLength(pre) + joiner.length };
}

// ---------------------------------------------------------------- one case

export interface V2Coordinates {
  readonly shape: Shape;
  readonly length: number;
  readonly depth: number;
  readonly language: Language;
  readonly lengthAt: number;
  readonly depthAt: number;
  readonly languageAt: number;
}

/** The feature assignment: a fixed arithmetic rule on the cell coordinates, decorrelated from the depth, length and language. */
export function featuresOf(shape: Shape, lengthAt: number, depthAt: number, languageAt: number): {
  readonly mode: QuestionMode;
  readonly longParagraph: false | 'middle' | 'cut';
  readonly nearDuplicate: boolean;
  readonly dense: boolean;
} {
  const titled = shape === 'drive-doc' || shape === 'adr-file';
  // A linear form with a coefficient on every coordinate, so the control (named) and section shares are spread over every depth, length and language
  // (the first draft used cell % 5 with cell = 15 l + 3 d + g, which left depths 50 and 90 without any named case).
  const slot = (lengthAt + 2 * depthAt + 3 * languageAt) % 5;
  const mode: QuestionMode = slot === 0 ? 'named' : titled && slot >= 3 ? 'section' : 'paraphrase';
  const lp = (lengthAt + depthAt + languageAt) % 3 === 0;
  return {
    mode,
    longParagraph: lp ? ((depthAt + languageAt) % 2 === 0 ? 'middle' : 'cut') : false,
    nearDuplicate: mode !== 'section' && (lengthAt + 3 * depthAt + 2 * languageAt) % 4 === 1,
    dense: (lengthAt + depthAt + languageAt) % 2 === 0,
  };
}

const tierName = (length: number): string => (length === ADR_FILE_BYTES ? '2mb' : `${length / 1000}k`);
export const caseIdV2 = (shape: Shape, length: number, depth: number, language: Language): string => `ch1v2-${shape}-${tierName(length)}-d${depth}-${language}`;

const rowHeader = (language: Language): string => (language === 'ko' ? '항목 | 설명 | 담당자 | 금액 | 날짜' : 'Item | Description | Owner | Amount | Date');

export function buildCaseV2(coordinates: V2Coordinates): ChunkEvalCaseV2[] {
  const { shape, length, depth, language } = coordinates;
  const id = caseIdV2(shape, length, depth, language);
  const random = seeded(`${CORPUS_V2_SEED}:${id}`);
  const feature = featuresOf(shape, coordinates.lengthAt, coordinates.depthAt, coordinates.languageAt);
  const kinds = SHAPE_KINDS[shape];
  const kind = kinds[(coordinates.lengthAt + 2 * coordinates.depthAt + coordinates.languageAt) % kinds.length] as NeedleKind;
  const table = shape === 'workbook';
  const sectioned = SHAPE_SECTIONS[shape] > 0;
  const titled = feature.mode === 'section';
  const measure = length === ADR_FILE_BYTES ? (text: string): number => Buffer.byteLength(text, 'utf8') : cpLength;
  const separator = table ? '\n' : '\n\n';

  // names and topics
  const used = new Set<string>();
  const codename = (): string => (language === 'ko' && kind !== 'code-line' ? hangulName(random, used) : latinName(random, used));
  const code = codename();
  const decoyNames = Array.from({ length: 8 }, codename);
  const targetTopic = between(random, 0, TOPICS.length - 1);
  const otherTopics = TOPICS.map((_, at) => at).filter((at) => at !== targetTopic);
  for (let at = otherTopics.length - 1; at > 0; at -= 1) {
    const swap = between(random, 0, at);
    [otherTopics[at], otherTopics[swap]] = [otherTopics[swap] as number, otherTopics[at] as number];
  }
  let topicCursor = 0;
  const otherTopic = (): number => otherTopics[topicCursor++ % otherTopics.length] as number;
  const needleTopicText = (index: number, forKind: NeedleKind): string => (forKind === 'code-line' ? (TOPICS[index] as Topic).en.n : topicText(index, language).n);
  const freshCode = (forKind: NeedleKind): string => (forKind === 'code-line' ? latinName(random, used) : pick(random, decoyNames));

  // the needle
  const needleSlots = slotValues(kind, language, random, code, needleTopicText(targetTopic, kind));
  const needleText = renderNeedle(kind, language, needleSlots);
  const sameKindDecoy = (): string => {
    const decoyKind = (random() < 0.5 ? kind : pick(random, table ? (['sheet-row'] as const) : kinds)) as NeedleKind;
    const index = otherTopic();
    return renderNeedle(decoyKind, language, slotValues(decoyKind, language, random, freshCode(decoyKind), needleTopicText(index, decoyKind)));
  };

  // the long paragraph's size and target offset: reachable at the requested depth (generic rule, fixed before any run)
  const margin = 40;
  const high = (depth / 100) * length - margin;
  const low = (1 - depth / 100) * length - margin;
  const middleMax = Math.floor(Math.min(LONG_PARAGRAPH_MAX, length * 0.5, 3 * Math.min(high, low)));
  const cutMax = Math.floor(Math.min(LONG_PARAGRAPH_MAX, length * 0.5, low + Math.max(0, Math.min(800, high))));
  const longSize = feature.longParagraph === false ? 0 : between(random, 1300, Math.max(1300, feature.longParagraph === 'cut' ? cutMax : middleMax));
  // Target offset of the needle in the paragraph, kept inside what the requested depth allows (and the middle third for lp-middle).
  const longTarget =
    feature.longParagraph === false
      ? 0
      : feature.longParagraph === 'cut'
        ? Math.max(0, Math.min(800, Math.floor(high), longSize))
        : Math.max(Math.ceil(longSize / 3), longSize - Math.floor(low), Math.min(between(random, Math.floor(longSize * 0.4), Math.floor(longSize * 0.6)), Math.floor((2 * longSize) / 3), Math.floor(high)));
  const extraLong = feature.longParagraph === false ? 0 : length >= 60_000 ? 2 : length >= 20_000 ? 1 : 0;

  // filler
  const partCount = sectioned ? SHAPE_SECTIONS[shape] : 1;
  const sectionTarget = shape === 'adr-file' ? ADR_SECTION_CODE_POINTS : DRIVE_SECTION_CODE_POINTS;
  const secCount = titled ? Math.max(2, Math.ceil(length / sectionTarget)) : 1;
  const base0 = length <= 6_000 ? 2 : length <= 20_000 ? 3 : 5;
  const attributeCount = feature.mode !== 'named' && !table ? (feature.dense ? 6 : 2) : 0;
  const topicCount = feature.mode === 'paraphrase' && !table ? (feature.dense ? 3 : 1) : 0;
  const crossCount = titled ? (feature.dense ? 6 : 2) : 0;
  // Decoys are added on top of the filler, so their volume (about 130 code points each) is taken off the filler budget.
  const decoyUnits = (feature.dense ? base0 * 3 : base0) + attributeCount + topicCount + crossCount + (feature.nearDuplicate ? 3 : 0);
  const fillTotal = Math.max(length * 0.3, length - longSize - extraLong * 1500 - decoyUnits * 130);
  const unitPoints = shape === 'slack-thread' ? 60 : 150;
  const fillerShape: Shape = titled ? 'mail' : shape;
  const newUnit = (): string => {
    if (table) {
      const item = random() < 0.5 ? pick(random, decoyNames) : `${pick(random, ITEM_WORDS)}-${between(random, 1, 40)}`;
      return `${item} | ${needleTopicText(pick(random, otherTopics), 'sheet-row')} | ${person(random, language)} | ${money(random)} | ${day(random, language)}`;
    }
    return paragraph(random, language, decoyNames, code, fillerShape, unitPoints);
  };
  const parts: Part[] = [];
  const share = fillTotal / (partCount * secCount);
  const doc = titled ? (DOC_TITLE[shape as 'drive-doc' | 'adr-file'][language] as string) : null;
  for (let partAt = 0; partAt < partCount; partAt += 1) {
    const secs: Sec[] = [];
    for (let secAt = 0; secAt < secCount; secAt += 1) {
      const name = titled ? sectionName(language, secAt) : undefined;
      const units: string[] = [];
      let size = name === undefined ? 0 : measure(name.title) + 2;
      if (table) {
        units.push(rowHeader(language));
        size += measure(units[0] as string) + 1;
      }
      while (size < share) {
        const unit = newUnit();
        units.push(unit);
        size += measure(unit) + (table ? 1 : 2);
      }
      secs.push({ title: name === undefined ? null : name.title, units });
    }
    parts.push({
      frame: sectioned ? frameOf(shape, language, partAt, partCount) : '',
      title: table ? `${language === 'ko' ? '예산' : 'Budget'} ${partAt + 1}` : '',
      table,
      lead: doc,
      secs,
    });
  }

  // Units that must stay out of the named section (same-kind decoys, attribute-word decoys, cross-references): tracked by text.
  const avoided = new Set<string>();
  const insertUnit = (text: string, avoid: boolean, into?: { part: number; sec: number }): void => {
    const where = into ?? { part: sectioned ? between(random, 0, parts.length - 1) : 0, sec: between(random, 0, secCount - 1) };
    const units = ((parts[where.part] as Part).secs[where.sec] as Sec).units;
    units.splice(table ? between(random, 1, units.length) : between(random, 0, units.length), 0, text);
    if (avoid && titled) avoided.add(text);
  };

  // decoys
  const sameKind = feature.dense ? base0 * 3 : base0;
  for (let n = 0; n < sameKind; n += 1) insertUnit(sameKindDecoy(), true);
  const attributeDecoy = ATTRIBUTE_DECOYS[kind];
  if (feature.mode !== 'named' && !table && attributeDecoy !== undefined) {
    for (let n = 0; n < attributeCount; n += 1) insertUnit(attributeDecoy[language](topicText(otherTopic(), language).q), true);
  }
  if (feature.mode === 'paraphrase' && !table) {
    for (let n = 0; n < topicCount; n += 1) insertUnit((pick(random, TOPIC_DECOYS[language]) as (topic: TopicText) => string)(topicText(targetTopic, language)), false);
  }
  if (feature.longParagraph !== false && extraLong > 0) {
    for (let n = 0; n < extraLong; n += 1) insertUnit(longParagraph(random, language, decoyNames, code, between(random, 1300, 1700), fillerSentence(random, language, decoyNames, code), 0, false).text, false);
  }

  // near-duplicates of the needle: same kind and template, another topic and codename, the answer value changed
  const nearSlots: SlotsV2[] = [];
  const nearTexts: string[] = [];
  if (feature.nearDuplicate) {
    for (let n = 0; n < 3; n += 1) {
      const slots = slotValues(kind, language, random, freshCode(kind), needleTopicText(otherTopic(), kind));
      const merged: SlotsV2 = kind === 'date' ? { ...slots, a: needleSlots.a } : slots;
      nearSlots.push(merged);
      nearTexts.push(renderNeedle(kind, language, merged));
    }
  }
  const quoted = (text: string, depthMarks: number): string => {
    const marker = '> '.repeat(depthMarks);
    return `${QUOTE_LEAD[language](day(random, language), person(random, language))}\n${marker}${text}\n${marker}${fillerSentence(random, language, decoyNames, code)}`;
  };
  const quoteShape = shape === 'mail' || shape === 'thread';
  const ndUnit = (text: string, order: number): string => (quoteShape ? quoted(text, order === 1 ? 2 : 1) : text);
  const codeBlock = shape === 'adr-file' && kind === 'code-line' && feature.longParagraph === false;

  // the needle unit (possibly a long paragraph or a fenced block) and its cluster with adjacent near-duplicates
  let needleUnit = needleText;
  let needleOffset = 0;
  let lpPlacement: 'middle' | 'cut' | undefined;
  if (feature.longParagraph !== false) {
    const built = longParagraph(random, language, decoyNames, code, longSize, needleText, longTarget, table, feature.longParagraph === 'middle');
    needleUnit = built.text;
    needleOffset = built.needleOffset;
    lpPlacement = feature.longParagraph;
  } else if (codeBlock && nearTexts.length > 0) {
    const lines = [nearTexts[0] as string, nearTexts[1] as string, needleText, nearTexts[2] as string];
    needleUnit = `\`\`\`ts\n${lines.join('\n')}\n\`\`\``;
    needleOffset = cpLength(`\`\`\`ts\n${lines.slice(0, 2).join('\n')}\n`);
  }
  let cluster = needleUnit;
  if (nearTexts.length > 0 && !codeBlock) {
    const before = ndUnit(nearTexts[0] as string, 0);
    const after = ndUnit(nearTexts[1] as string, 1);
    cluster = [before, needleUnit, after].join(separator);
    needleOffset += cpLength(before) + separator.length;
    insertUnit(ndUnit(nearTexts[2] as string, 0), true);
  }

  // The named section: the one the requested depth falls into once everything else is in. The units that must stay out of it are
  // moved to another section and the cross-references (which carry the section's title words) are rebuilt for it, until stable.
  let star = -1;
  let starFor = -2;
  let cross: string[] = [];
  // Prefer sections AFTER the named one (the named section's start then does not move); the last section sends them before.
  const otherSec = (): { part: number; sec: number } => {
    if (star < secCount - 1) return { part: 0, sec: between(random, star + 1, secCount - 1) };
    return { part: 0, sec: between(random, 0, Math.max(0, star - 1)) };
  };
  const starAt = (): number => {
    const now = boundaries(parts, table);
    const point = (depth / 100) * (now.total + cpLength(cluster) + separator.length) - needleOffset;
    const edges = (parts[0] as Part).secs.map((_, at) => (now.candidates.find((candidate) => candidate.sec === at) as Candidate).start);
    return edges.reduce((best, edge, at) => (edge <= point ? at : best), 0);
  };
  if (titled) {
    for (let round = 0; round < 12; round += 1) {
      // The section is re-evaluated for three rounds, then frozen (a two-section 6k item would otherwise swing between both).
      if (round < 3) star = starAt();
      let changed = false;
      if (starFor !== star) {
        for (const sec of (parts[0] as Part).secs) {
          for (let at = sec.units.length - 1; at >= 0; at -= 1) if (cross.includes(sec.units[at] as string)) sec.units.splice(at, 1);
        }
        cross.forEach((text) => avoided.delete(text));
        const text = CROSS_REFERENCE[language](sectionName(language, star).words);
        cross = crossCount > 0 ? [text] : [];
        for (let n = 0; n < crossCount; n += 1) insertUnit(text, true, otherSec());
        starFor = star;
        changed = true;
      }
      const inside = ((parts[0] as Part).secs[star] as Sec).units;
      for (const text of [...inside]) {
        if (!avoided.has(text)) continue;
        inside.splice(inside.indexOf(text), 1);
        const into = otherSec();
        const units = ((parts[0] as Part).secs[into.sec] as Sec).units;
        units.splice(between(random, 0, units.length), 0, text);
        changed = true;
      }
      if (!changed) break;
    }
    if (star !== starFor || ((parts[0] as Part).secs[star] as Sec).units.some((text) => avoided.has(text))) throw new Error(`corpus-v2: the named section did not settle in ${id}`);
  }
  const star_ = titled ? sectionName(language, star) : undefined;

  // placement: the unit boundary whose needle offset is nearest the requested depth (inside the named section when there is one)
  const layout = boundaries(parts, table);
  const totalAfter = layout.total + cpLength(cluster) + separator.length;
  let chosen: Candidate | undefined;
  let chosenError = Infinity;
  for (const candidate of layout.candidates) {
    if (titled && !(candidate.sec === star)) continue;
    const error = Math.abs((candidate.start + needleOffset) / totalAfter - depth / 100);
    if (error < chosenError) {
      chosen = candidate;
      chosenError = error;
    }
  }
  const place = chosen as Candidate;
  ((parts[place.part] as Part).secs[place.sec] as Sec).units.splice(place.at, 0, cluster);

  // rendering (a titled Drive doc is rendered as plain text AND Markdown; every other case once)
  const formats: readonly ('text' | 'markdown')[] = titled ? (shape === 'drive-doc' ? ['text', 'markdown'] : ['markdown']) : ['text'];
  const question = ((): string => {
    if (feature.mode === 'named') return needleTemplate(kind, language).question(code);
    const topic = topicText(targetTopic, language);
    if (feature.mode === 'section') {
      const sentence = (SECTION_QUESTIONS[kind] as Readonly<Record<Language, string>>)[language];
      return `${(star_ as SectionName).reference}${sentence}`;
    }
    return (pick(random, QUESTIONS[kind][language]) as (q: string) => string)(topic.q);
  })();
  const answers = answersOf(kind, needleSlots);
  if (feature.mode !== 'named') {
    const lower = question.toLowerCase();
    const forbidden = [code, ...answers, needleSlots.topic, topicText(targetTopic, language).n];
    for (const word of forbidden) if (word.length > 0 && lower.includes(word.toLowerCase())) throw new Error(`corpus-v2: degenerate question in ${id}: contains "${word}"`);
  }
  const shared = (TOPICS[targetTopic] as Topic).shared;
  const tags: FeatureTag[] = [feature.mode === 'section' ? 'section-name' : feature.mode];
  if (feature.mode !== 'named') tags.push('no-codename');
  if (feature.mode === 'paraphrase') tags.push(shared ? 'topic-shared' : 'topic-disjoint');
  if (lpPlacement !== undefined) tags.push('long-paragraph', lpPlacement === 'middle' ? 'lp-middle' : 'lp-cut');
  if (feature.nearDuplicate) tags.push('near-duplicate');
  if (feature.dense) tags.push('dense');

  return formats.map((format): ChunkEvalCaseV2 => {
    const rendered = parts.map((part) => ({ part, ...renderBody(part, separator, format) }));
    const casePartsOut: CasePart[] = rendered.map(({ part, body }) => ({ frame: part.frame, title: part.title, body, ...(table ? { kind: 'table' as const } : {}) }));
    const joined = chunking.joinSections(casePartsOut.map((part) => ({ frame: part.frame, body: part.body, ...(part.kind === undefined ? {} : { kind: part.kind }) })));
    const prepared = joined.text;
    const first = prepared.indexOf(needleText);
    if (first < 0 || prepared.indexOf(needleText, first + 1) >= 0) throw new Error(`corpus-v2: needle not unique in ${id}`);
    const start = cpLength(prepared.slice(0, first));
    const range = (text: string): { start: number; end: number } => {
      const at = prepared.indexOf(text);
      if (at < 0) throw new Error(`corpus-v2: text missing from ${id}`);
      const from = cpLength(prepared.slice(0, at));
      return { start: from, end: from + cpLength(text) };
    };
    const section = ((): ChunkEvalCaseV2['section'] => {
      if (star_ === undefined) return undefined;
      const marks = (rendered[0] as { titleStarts: number[] }).titleStarts;
      const from = cpLength(prepared.slice(0, marks[star] as number));
      const to = star + 1 < marks.length ? cpLength(prepared.slice(0, marks[star + 1] as number)) : cpLength(prepared);
      return { number: star_.number, title: star_.title, start: from, end: to };
    })();
    return {
      id: format === 'text' && titled ? `${id}-text` : format === 'markdown' && shape === 'drive-doc' ? `${id}-markdown` : id,
      shape,
      length,
      depth,
      language,
      needleKind: kind,
      parts: casePartsOut,
      prepared,
      sections: joined.sections,
      question,
      needle: { text: needleText, start, end: start + cpLength(needleText) },
      codename: code,
      topic: { needle: needleSlots.topic, question: topicText(targetTopic, language).q },
      answers,
      mode: feature.mode,
      tags,
      ...(lpPlacement === undefined
        ? {}
        : { longParagraph: { placement: lpPlacement, ...range(needleUnit), needleFraction: Math.round((needleOffset / cpLength(needleUnit)) * 1000) / 1000 } }),
      nearDuplicates: nearTexts.map((text, at) => ({ kind, slots: nearSlots[at] as SlotsV2, text, ...range(text) })),
      ...(section === undefined ? {} : { section }),
      ...(titled && shape === 'drive-doc' ? { pairId: id, format } : {}),
    };
  });
}

/**
 * Every case of v2, in a fixed order: 7 shapes x 4 lengths x 5 depths x 3 languages = 420 cells, one case each (a titled Drive-doc
 * cell yields a plain-text and a Markdown case), plus a reduced 2 MiB ADR-file tier of 3 cases (one per language, depths 30 / 50 / 70).
 */
export function generateCorpusV2(): ChunkEvalCaseV2[] {
  const cases: ChunkEvalCaseV2[] = [];
  for (const shape of SHAPES) {
    LENGTHS.forEach((length, lengthAt) =>
      DEPTHS.forEach((depth, depthAt) => LANGUAGES.forEach((language, languageAt) => cases.push(...buildCaseV2({ shape, length, depth, language, lengthAt, depthAt, languageAt })))),
    );
    if (shape === 'adr-file') {
      LANGUAGES.forEach((language, languageAt) => {
        const depthAt = ADR_FILE_V2_DEPTH_AT[languageAt] as number;
        cases.push(...buildCaseV2({ shape, length: ADR_FILE_BYTES, depth: DEPTHS[depthAt] as number, language, lengthAt: LENGTHS.length, depthAt, languageAt }));
      });
    }
  }
  return cases;
}

function caseDigest(item: ChunkEvalCaseV2): string {
  return createHash('sha256')
    .update(
      JSON.stringify([
        item.id,
        item.shape,
        item.length,
        item.depth,
        item.language,
        item.needleKind,
        item.question,
        item.needle,
        item.parts,
        item.prepared,
        item.sections,
        item.codename,
        item.topic,
        item.answers,
        item.mode,
        item.tags,
        item.longParagraph ?? null,
        item.nearDuplicates,
        item.section ?? null,
        item.pairId ?? null,
        item.format ?? null,
      ]),
    )
    .digest('hex');
}

/** sha256 over the version, the seed and every case digest, in order. Changes with any byte of any case or tag. */
export function corpusV2Digest(cases: readonly ChunkEvalCaseV2[]): string {
  const hash = createHash('sha256');
  hash.update(`${CORPUS_V2_VERSION}\n${CORPUS_V2_SEED}\n${cases.length}\n`);
  for (const item of cases) hash.update(`${caseDigest(item)}\n`);
  return hash.digest('hex');
}
